import{_ as t,a as r}from"./chunks/ccb3afe57e2f3cb16a94.D7fTR6Si.js";import{_ as o,C as l,o as s,c as i,j as e,a as n,E as d,a5 as h}from"./chunks/framework.DNkHA0lr.js";const y=JSON.parse('{"title":"我今年 28 岁。这是我想对 18 岁的自己说的话。","description":"","frontmatter":{"title":"我今年 28 岁。这是我想对 18 岁的自己说的话。","originalTitle":"I’m 28. Here’s What I Would Tell My 18-Year-Old Self.","date":"2024-12-14","originalUrl":"https://thedankoe.com/letters/im-28-heres-what-i-would-tell-my-18-year-old-self/","minutes":13,"sourceHash":"6a60752e5b24f756c2f1eb2d682f5a1aa0cd430cdafd40e5369cfd70c9c19818","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/im-28-heres-what-i-would-tell-my-18-year-old-self/"}]]},"headers":[],"relativePath":"letters/im-28-heres-what-i-would-tell-my-18-year-old-self.md","filePath":"letters/im-28-heres-what-i-would-tell-my-18-year-old-self.md"}'),c={name:"letters/im-28-heres-what-i-would-tell-my-18-year-old-self.md"};function u(m,p,_,f,q,b){const a=l("ArticleMeta");return s(),i("div",null,[p[0]||(p[0]=e("h1",{id:"我今年-28-岁。这是我想对-18-岁的自己说的话。",tabindex:"-1"},[n("我今年 28 岁。这是我想对 18 岁的自己说的话。 "),e("a",{class:"header-anchor",href:"#我今年-28-岁。这是我想对-18-岁的自己说的话。","aria-label":'Permalink to "我今年 28 岁。这是我想对 18 岁的自己说的话。"'},"​")],-1)),d(a),p[1]||(p[1]=h('<p>18 岁那年，我感到很迷茫。</p><p>我一直在为人生最大的问题寻找一套简洁明了的答案。我们为什么活在这里？我该如何度过自己的人生？我该如何避免变成周围那些人的样子，还是说每个人注定都会变得被动、不快乐、缺乏能量？我该如何充分利用被赋予的这次机会？</p><p>但无论我读了多少本书，都好像找不到答案。我找到的只是没有明确结论的争论、由那些看起来并不快乐的人提出的论点，以及一旦脱离具体语境就显得说不通的高度自信的信念。</p><p>在这个星球上生活了几千年，我们竟然还没有一套所有人都能认同的原则、价值观或经验教训？这是某种病态的宇宙玩笑吗？我是说，说真的……这甚至不止是人生的大问题。种子油。商业模式。恋爱教条。宗教教义。每个人都在打这场概念之战，而没有哪一方是明确的赢家。</p><p>看起来演化与熵增是携手并进的，而且远远超出了物理世界的范畴。我们会紧紧抓住那些能带给我们一丝清晰感的信念，把它们当作唯一真理去宣扬，而当这个信念不可避免地崩塌时，我们往往还拒绝改变主意。</p><p>所以，如果说我意识到了一件事，那就是——</p><p>唯一正确的生活方式，就是不像任何其他人那样去生活。</p><p>美好人生始于你拒绝任何一种“别的方式”。</p><p>最好的做法是从零开始，自己去把它弄明白。</p><p>信念、概念和建议就像工具。它们对实现某个目标是有用的，但一旦那个目标达成，这个工具就不再适配那颗螺丝了。所以，与其去寻找一把能适配那颗根本不存在的“唯一真螺丝”或那块木板、那栋房子的“唯一真工具”，更明智的做法是训练一颗能够自己创造工具、规划自己的房子、并愿意从一个有经验积累的地方重新开始的心智——这样，当微观和宏观的环境不可避免地发生变化时，它就能随之适应。</p><p>如果我能穿越回过去，给 18 岁的自己写一封信，我会这样说。</p><h2 id="_1-如果你不为自己创造一个目标-你就会被别人分配一个" tabindex="-1">1）如果你不为自己创造一个目标，你就会被别人分配一个 <a class="header-anchor" href="#_1-如果你不为自己创造一个目标-你就会被别人分配一个" aria-label="Permalink to &quot;1）如果你不为自己创造一个目标，你就会被别人分配一个&quot;">​</a></h2><p>大多数人到 18 岁时，人生早已被安排好了——即便他们自己以为并非如此。</p><p>逆转这一过程的唯一方法，就是深入理解心智的运作方式。</p><p>你有意识或无意识设定的目标，塑造了你感知世界的方式。</p><p>多巴胺会喷涌进入你的大脑，向你发出信号，表明某条信息很重要、有助于你实现目标。</p><p>你的大脑储存那条信息，你据此行动，如果你朝着目标取得了进展，你的大脑就会把这个反馈解读为“成功”，于是一套系统开始固化下来。重复这个行为所需的努力越来越少，它就变成了习惯。这就是我们所说的“条件反射”或“程序化”。</p><p>你整个人生，都取决于被植入你脑中的那一连串目标，因为正是这些目标，塑造了你在每一个瞬间，对所接触到的一切信息的感知方式、解读方式和行动方式。</p><p>这里最大的问题在于：当我们还年幼时，我们几乎无法控制自己被分配到什么目标。而如果我们没有同样理解这一过程的、具有高能动性的父母，我们就会被动服从于主流体系。在这种情况下，那就是：上学、找工作，然后在某个年纪退休——而你能拿到的远比当初被承诺的要少得多。这些就是从出生起就被注入你脑中的目标。</p><p>大多数孩子每天被扔在一位受政府培训的“专家”面前好几个小时，吸收那些唯一目的就是把他们培养成“有用的劳动力”的信息。这一点毫无争议。学校体系服务于创造它的那个东西：政府。而你服务政府的方式，就是成为一个有用的劳动力、按时纳税，以此类推。</p><p>当然，这并非全然是坏事。在很多情况下它是必要的。许多“有用的劳动力”也能过上很棒的生活。但我说的不是他们。我是在对过去的自己说话。那个明知自己注定要有更大成就、无法忍受平庸人生想法的孩子。</p><p>对那个孩子，我想告诉他：平庸与卓越之间的差别，就是低能动性与高能动性之间的差别。在这个语境下，<strong>高能动性的人是那些为自己创造目标、并主动去追求它们、无需征得他人许可的人。</strong> 低能动性的人则是那些被分配了目标、并去追求它们，因为他们的心智根本看不到还有别的选择。</p><p>这就是自由个体与仆从、创业者与雇员、通才与专才之间的区别，它为这封信接下来的内容定下了基调。其余每一条经验教训，都聚焦于如何思考、如何学习、以及如何生活，从而培养并善用你的能动性。</p><p>如果你不去创造一个目的——一个能让你据以对齐决策的、宏大而有意义的目标——那么你就无法掌控自己的潜力。</p><h2 id="_2-常常思考你不想要的东西" tabindex="-1">2）常常思考你不想要的东西 <a class="header-anchor" href="#_2-常常思考你不想要的东西" aria-label="Permalink to &quot;2）常常思考你不想要的东西&quot;">​</a></h2><blockquote><p>人不应惧怕死亡，而应惧怕从未真正开始生活。——马可·奥勒留（Marcus Aurelius）</p></blockquote><p>你从对正能量的赞美中，什么都学不到。</p><p>这是人类体验中的一个“特性”，而不是“缺陷”，你可以学会去整合和利用它。我们的大脑天生是为生存而布线的。当我们感到舒适时——在当今世界这种情况相当常见——我们就更容易陷入那些慢慢将我们拖入混乱的陷阱与享乐之中。</p><p>你只能从错误中学习。你只能从挣扎中学习。你只能在心智处于一种迫切想要学习、适应、进化的状态下才能学习，因为那样它才能减少再次经历那种痛苦的可能性。也就是当你的心智一直在与某个问题较劲，直到孕育出一个解决方案的时候。</p><p>所以，朝理想生活方式迈进的诀窍，并不是持续保持正能量、想象理想结果。这些当然有帮助，但它们缺少了方程式的另一半。</p><p>你必须经常去思考自己不想要的东西。你必须形成一种“反向愿景”（anti-vision），把它当作一种强大的燃料源，推动你朝一个独特的未来火箭般前进。</p><p>愿景或反向愿景都不是一蹴而就的。你要通过经历一笔一笔地去添色。你要允许自己搞砸。你要允许自己感到害怕。你要允许自己踏入未知去犯错、去挣扎、去与自己的心魔搏斗，然后慢慢把它想明白。</p><p>养成反思自己经历的习惯——在大多数人任由生活中的问题悄然滑过去的时候。你再也不想经历什么？你目前的行为正在把你引向何处？有什么痛苦是你曾经因为当下心智太封闭、想不出解决办法而选择忽视的？</p><p>当你身处事发当下的激烈情绪中时，你的心智并不处于开放状态。你不会有心思去解决它。如果你不在自己能够进行反思的状态下去做自我反思，你就不会改变。而你会让错误不断累积，直到为时已晚。</p><h2 id="_3-专注于-为什么-看着-怎么做-自然浮现" tabindex="-1">3）专注于“为什么”，看着“怎么做”自然浮现 <a class="header-anchor" href="#_3-专注于-为什么-看着-怎么做-自然浮现" aria-label="Permalink to &quot;3）专注于“为什么”，看着“怎么做”自然浮现&quot;">​</a></h2><p>人类是通才。</p><p>我们不像狮子或北极熊那样只能在单一的细分领域里生存——把它们扔进另一种环境就会活不下去。我们会打造衣服、电脑、概念这样的工具，帮助自己适应新的物理、心理和数字环境。</p><p>问题出现在，当一个人被骗，以为自己就是一件工具的时候。</p><p>那正是那条无意识的道路所导向之处。你去上学，是为了地位和安全感。你专注于成为一名医生、律师、艺术家或程序员。你的心智被那个目标框住了，你也因此没能学到那个框架之外的任何东西。</p><p>毫怪你会害怕人工智能和自动化。因为你自己早已是一台机器了。你是一件工具，却在担心被另一件工具取代。你不是一个拥有执行功能、能够创造叙事而非成为叙事一部分的人类。你已经放弃了培育愿景、给工具分配目标、以及学习完成这两者所需一切的能力。</p><p>当你深入挖掘自己的欲望时，你会意识到，你其实并不真的在乎成为医生、律师还是艺术家。你会意识到，那些不过是你可以拿来给自己混乱的心智带来即时——却是虚假——秩序感的整洁头衔。</p><p>归根结底，人类拥有创造、扩展和超越的渴望。你想成为医生，是为了帮助他人。你想成为艺术家，是为了满足自己的创造性需求。你想成为作家，是为了追求精通。但接受这一点极其困难，因为一旦你接受了它，你就只剩下一个选项：为自己的人生承担全部责任。</p><p>实现这些欲望的路径，既有无限种，也可以说只有一种。</p><p>唯一能弄清楚<strong>你</strong>究竟注定要做什么的方法，就是始终聚焦于“<strong>为什么</strong>”：创造、扩展和超越。创造出有价值的东西去帮助他人。拓展自身的复杂性，去应对更大的挑战。超越并涵纳此前各个发展阶段，走向一种更整合的世界观。</p><p>你做事的“<strong>怎么做</strong>”会随时代而变。它一直如此，也将永远如此。而你做事的“<strong>为什么</strong>”从未改变过，除非你被自己更深层的目的分了心。</p><p>如果你创造出一个能随你一同进化的目的，常常思考自己不想要什么，并且避免执着于那些“最好”或“最高地位”的工具去完成任务，你就不再会被新技术和变化所威胁。</p><p>不要只为了做某个特定工作而学技能。要学任何能帮你打造理想生活方式所必需的技能。什么都去尝试，直到你找到那件让你无法自拔的事，而当那件事不可避免地衰败时，就再重新来一遍。</p><p>顺便说一句，尤其是 AI，如果没有<strong>应用场景</strong>，它就毫无用处。OpenAI 只有在变成一个聊天应用之后才真正变得有用。Cursor 通过把 AI 放进一个编辑器里，让 AI 变得有用。<a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a> 这个月开始也将做同样的事，我们的 AI 功能即将上线。</p><h2 id="_4-如果你不在建造-你就在消亡" tabindex="-1">4）如果你不在建造，你就在消亡 <a class="header-anchor" href="#_4-如果你不在建造-你就在消亡" aria-label="Permalink to &quot;4）如果你不在建造，你就在消亡&quot;">​</a></h2><blockquote><p>三种最有害的瘾，是海洛因、碳水化合物，以及月薪。——纳西姆·尼古拉斯·塔勒布（Nassim Nicholas Taleb）</p></blockquote><p>对于长期主义思考者而言，创业是唯一合乎逻辑的选择。</p><p>你可以在一份工作里做一个高能动性的人，并因主动出击、解决问题而获得丰厚的回报——但事实依然是，你无法掌控那个愿景。你无法掌控那个目标。你无法掌控自己学什么、如何思考、以及你的人生最终会走向何处。你当然拥有一定的控制权，但它仍然受限于那个允许你生存下去的人。</p><p>如果你想朝着自己的目的迈进，善用思考“不想要什么”所产生的能量，并把自己培养成一个深度通才，你就必须成为一个建造者。</p><p>如果你能每天花 8 个小时去建造别人的梦想，你就能拿出 1 个小时来建造自己的梦想。每个人都能在自己的日常安排中挤出这一个小时。而对于那些觉得这微不足道的人——你以为 99% 的人都是从哪里起步的？</p><p>每个创业者真的都会魔法般地开始每天工作12个小时吗？还是说你缺乏认知视角，喜欢用一种舒适的想法来安慰自己——认为他们和你一样没有责任要承担？一个小时很快就能变成365个小时，而365个小时足以让你打造出一些了不起的东西。</p><p>每天预留出1个小时。</p><p>把一个项目当作拼图的一块，规划出你理想生活的蓝图。</p><p>允许自己去开始、去搞砸、去犯错。</p><p>学习那些打造属于自己的事物所需的众多技能。</p><p>说实话，我并不认为工作是无用或糟糕的。但我非常清楚地意识到，工作会让你变得自满，并对你的心理状态构成危险。你看，在一份工作中，你并不能掌控&quot;技能:挑战&quot;的比例。</p><p><img src="'+t+'" alt=""></p><p>一个具有挑战性的目标，正是让生活变得有意义的原因。但如果你的技能水平不足以匹配这个挑战，你就会感到焦虑。而如果你的技能对这个挑战来说绰绰有余，你就会感到无聊。关键在于，把目标设定得刚好超出你当前的能力范围。这样，你的能力才会被真正考验，你也才能感受到进步带来的愉悦感。</p><p><img src="'+r+'" alt=""></p><p>工作对于技能积累、经验获取和人脉建立是有用的，但你只能爬到梯子的某个高度，再往上对大多数人来说就变得不可行了。最初的6个月过后，重复性就会开始显现。你不会再感受到挑战。你更有可能继续留在那份工作上，不是因为它令人满足，而是因为它每月给你带来稳定的薪水。</p><p>如果你不是一个多面手，你就无法爬到顶端。而到了那个时候，你依然会发现，打造属于自己的事业更值得。</p><p>但这里有个关键点。无聊和焦虑会导致精神熵增。无聊会导致自我中心化，你开始思考自己本可以做哪些更好的事情。焦虑会导致自我意识过强，你会专注于自己的缺点，觉得自己不够好。这两者都会让负面想法不断增多，摧毁你脑中的秩序和专注力，最终导致混乱。自然而然地，你会去寻求快感来麻痹这种痛苦，因为你觉得自己别无选择。你不需要在工作中做到最好，于是你就任由坏习惯在生活中不断累积。</p><p>如果你没有在打造与你理想未来一致的事物，那你其实是在走向死亡。</p><h2 id="_5-金钱是个人成长的工具" tabindex="-1">5) 金钱是个人成长的工具 <a class="header-anchor" href="#_5-金钱是个人成长的工具" aria-label="Permalink to &quot;5) 金钱是个人成长的工具&quot;">​</a></h2><blockquote><p>有特权却没有权力的人是一种浪费，而受过教育却没有影响力的人则是一堆毫无价值的垃圾。——J.D. 洛克菲勒（J.D. Rockefeller）</p></blockquote><p>我知道这很难让人相信，但金钱并不是那些心胸狭隘的人所认为的邪恶怪物。</p><p>事实上，成为一名创业者是我个人成长中最强大的催化剂。它迫使我提升了自己的能动性。它迫使我把生活中的其他方面理顺，比如健康和习惯，否则我的工作就会受到影响。它迫使我通过学习新技能、接受更有趣的挑战来拓展自我的复杂性。最后，它迫使我变得不那么自私。我的创作不仅是为了满足自己的创作欲望，更是为了帮助他人。</p><p>我理解你的思维可能受到了局限性信念的束缚，这种节俭的心态让你无法看到现实更美好的一面。我理解，如果你认同一种纯粹上升式的哲学——却未能整合&quot;更低层次的视角&quot;——把整个显现的世界都视为脏污且不道德的，那也没关系。我也理解，如果你对金钱的理解不是基于实验和亲身经历，而是基于那种&quot;富有和成功的人总是不道德的骗子&quot;的普遍叙事。</p><p>但改变生命的创造，从来不是靠捐款和慈善打造出来的。人类的福祉，也不是靠脱离现实、跑到森林里冥想来提升的。不道德的公司，不是靠抗议就能被瓦解的，而如果你不去创办一家能以更好的方式为人类做贡献的企业，你就是在通过自己的工作和无知，间接助长了那些邪恶——正是这种无知，才让那些不道德的公司得以爬到顶端。</p><p>再说了，你的生活难道不早已被金钱所支配了吗？难道你不需要先征服它，才能摆脱它的掌控吗？难道你不是在为一家靠向大多数满意的顾客出售产品来维持生存的公司打工吗？你对这唯一一件你似乎无法逃脱的东西怀有仇恨，难道你不是个伪君子吗？在我们这个现代世界里，人们以为可以通过幻想退回到过去那个&quot;更好&quot;的、欠发达的人类状态来逃避——那唯一的出路，难道不是去解决你的金钱问题，而不是去消除它吗？</p><p>人们厌恶金钱的根本原因，是因为金钱是一种价值的衡量标准。而价值，衡量的是有多少人支持和在乎你的创造。</p><p>按你付出的工作量来获得报酬，这本身就说不通。按你提供的价值来获得报酬，这才说得通，现实就是这样运作的。你可能不喜欢这一点，它可能也并不完全纯粹或神圣（因为没有什么是完全纯粹的，创造总是与毁灭相抵消的），但那些比你更富有的人，从定义上来说，就是比你更有价值的人，而这一点让你感到愤怒。</p><p>但你没有采取任何行动去改变，而是抱怨、埋怨自己工作这么辛苦却挣得这么少。你还没有意识到，为了在这个世界上带来你想看到的改变，你需要关注度、权力、地位，以及所有你所憎恨的那些东西。想象一下，如果耶稣基督、乔达摩佛陀，或者阿兰·瓦茨（Alan Watts），或者任何你视为指引方向和获得清晰思路的人物，没有关注度、权力或地位，会怎样。关键在于，这些东西并不是完全彻底邪恶的。它们的邪恶程度，取决于拥有它们的人的发展水平，以及解读它们的人的发展水平。</p><p>现实是，你是可以赚钱的。能赚多少，取决于你自己。事实上，这可能就是唯一一件真正阻碍你实现更有意义、更充实生活的东西。</p><p>如果最后这句话让你的大脑短路了，那说明你还有一些认知视角需要修炼。</p><p>这次就先到这里。</p><p>我还有几条经验想告诉你，但我会把它们留给以后的信件。</p><p>——丹（Dan）</p><hr><p><a href="/en/letters/im-28-heres-what-i-would-tell-my-18-year-old-self">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',84))])}const A=o(c,[["render",u]]);export{y as __pageData,A as default};
